import math
def n_choose_r(n, r):
    return math.factorial(n) // (math.factorial(r) * math.factorial(n - r))

print(n_choose_r(4, 2))   # 6, matching the 6 unordered pairs from 4 letters

def n_permute_r(n, r):
    return math.factorial(n) // math.factorial(n - r)

print(n_permute_r(4, 2) // math.factorial(2))   # 6, matching n_choose_r(4, 2) exactly

def pascals_triangle_row(n):
    return [n_choose_r(n, r) for r in range(n + 1)]

for n in range(5):
    print(pascals_triangle_row(n))

def combinations_with_repetition(n, r):
    return n_choose_r(n + r - 1, r)

print(combinations_with_repetition(5, 3))   # ways to choose 3 scoops from 5 flavors, repeats allowed
